import React from "react";
import { motion } from "framer-motion";

const MenusBox = ({ title, value, icon, onChange }) => {
  return (
    <motion.div
      className="p-4 rounded-xl shadow-md bg-gradient-to-r from-purple-500 to-indigo-600 text-white"
      whileHover={{ scale: 1.05 }}
    >
      <div className="flex justify-between items-center">
        <div className="w-full">
          <h4 className="text-sm font-medium mb-1">{title}</h4>
          <input
              type="text"
              value={value}
              onChange={(e) => onChange(e.target.value)}
              placeholder="Yangi menu nomini kiriting"
              className="text-2xl font-bold bg-transparent border-b border-white outline-none w-full 
             placeholder:text-sm placeholder:text-white/60 text-white"
          />
        </div>
        <div className="text-4xl ml-3">{icon}</div>
      </div>
    </motion.div>
  );
};

export default MenusBox;
